phase1.code:
use std::fmt::Display;

// ---- Trait bounds in function parameters ----

// ---- Impl Trait syntax ----
fn print_value(value: impl Display) {
    println!("{}", value);
}

// ---- Generic with trait bound ----
fn print_value_generic<T: Display>(value: T) {
    println!("{}", value);
}

// ---- Where clause ----
fn print_value_where<T>(value: T) 
where
    T: Display,
{
    println!("{}", value);
}

// ---- Multiple trait bounds ----
use std::fmt::Debug;

fn print_debug_display<T: Display + Debug>(value: T) {
    println!("Display: {}", value);
    println!("Debug: {:?}", value);
}

// ---- Trait bound with return type ----
fn get_default_value<T: Default + Display>() -> T {
    T::default()
}

// ---- Trait bound on struct ----
struct Pair<T> {
    first: T,
    second: T,
}

impl<T: Display> Pair<T> {
    fn print(&self) {
        println!("First: {}, Second: {}", self.first, self.second);
    }
}

// ---- Trait bound with where clause ----
struct Container<T, U>
where
    T: Display + Clone,
    U: Debug + Clone,
{
    item1: T,
    item2: U,
}

impl<T: Display + Clone, U: Debug + Clone> Container<T, U> {
    fn new(item1: T, item2: U) -> Self {
        Container { item1, item2 }
    }

    fn print(&self) {
        println!("Item1: {}, Item2: {:?}", self.item1, self.item2);
    }
}

// ---- Generic function with multiple bounds ----
fn compare_and_print<T: PartialEq + Display>(a: T, b: T) {
    println!("a: {}, b: {}", a, b);
    if a == b {
        println!("They are equal");
    } else {
        println!("They are different");
    }
}

// ---- Trait bound on associated type ----
struct Wrapper<T> {
    value: T,
}

impl<T: Display> Wrapper<T> {
    fn new(value: T) -> Self {
        Wrapper { value }
    }

    fn print(&self) {
        println!("Value: {}", self.value);
    }
}

fn main() {
    // ---- Using impl Trait ----
    print_value(42);
    print_value("hello");

    // ---- Using generic trait bound ----
    print_value_generic(3.14);

    // ---- Using where clause ----
    print_value_where("world");

    // ---- Multiple bounds ----
    print_debug_display(42);

    // ---- Default value ----
    let default: i32 = get_default_value();
    println!("Default: {}", default);
    let default_string: String = get_default_value();
    println!("Default string: {}", default_string);

    // ---- Struct with trait bound ----
    let pair = Pair {
        first: 10,
        second: 20,
    };
    pair.print();

    // ---- Container with where clause ----
    let container = Container::new(42, vec![1, 2, 3]);
    container.print();

    // ---- Compare and print ----
    compare_and_print(5, 5);
    compare_and_print(5, 10);
    compare_and_print("hello", "hello");

    // ---- Wrapper ----
    let wrapped = Wrapper::new(42);
    wrapped.print();

    let wrapped_str = Wrapper::new("hello");
    wrapped_str.print();
}

